#!/bin/bash
# Build a perf workspace for one finished run: hard-link copy of ws_8a (same frozen base c0e38f1f,
# original LLKs), the run's own tests/hal_llk copied in, and the HAL perf kernel generated by
# replacing each '#include "llk_X.h"' with '#include "../hal_llk/llk_X.h"' (same as the agents' HAL tests).
# Usage: setup_ws.sh <name> <run dir>
set -euo pipefail
P=/proj_sw/user_dev/ctr-sbratic/tools/perf_cycles; N=${1:?name}; R=${2:?run dir}
W=$P/ws/$N; T=$W/tt_metal/tt-llk/tests
[[ -d $W ]] || cp -al $P/ws_8a $W
# rm before writing: files are hard links shared with ws_8a and must never be written in place
rm -rf $T/hal_llk $W/tt_metal/tt-llk/perf_data $T/.pytest_cache
rm -f $T/sources/eltwise_binary_hal_test.cpp $T/python_tests/test_eltwise_binary_hal.py \
      $T/sources/eltwise_binary_fpu_perf_hal.cpp $T/python_tests/perf_eltwise_binary_hal.py
cp -a $R/ws/tt_metal/tt-llk/tests/hal_llk $T/hal_llk
args=()
for h in $(ls $T/hal_llk); do args+=(-e "s#^\#include \"$h\"#\#include \"../hal_llk/$h\"#"); done
sed "${args[@]}" $T/sources/eltwise_binary_fpu_perf.cpp > $T/sources/eltwise_binary_fpu_perf_hal.cpp
sed 's#sources/eltwise_binary_fpu_perf.cpp#sources/eltwise_binary_fpu_perf_hal.cpp#g' \
  $T/python_tests/perf_eltwise_binary.py > $T/python_tests/perf_eltwise_binary_hal.py
nhal=$(grep -c '^#include "../hal_llk/' $T/sources/eltwise_binary_fpu_perf_hal.cpp || true)
norig=$(grep '^#include "llk_' $T/sources/eltwise_binary_fpu_perf_hal.cpp | grep -vc '"llk_defs.h"' || true)  # llk_defs.h stays original, as in the agents' own HAL tests
same=$(cd $R/ws/tt_metal/tt-llk/tests/hal_llk && md5sum * | (cd $T/hal_llk && md5sum -c --quiet - >/dev/null && echo yes || echo NO))
{ echo "name=$N"; echo "run_dir=$R"; echo "hal_llk_files=$(ls $T/hal_llk | tr '\n' ' ')"
  echo "hal_llk_md5_equal_to_run=$same"; echo "perf_includes_to_hal_llk=$nhal"; echo "perf_includes_original_llk=$norig"; } > $W/SOURCE.txt
[[ $nhal == 7 && $norig == 0 && $same == yes ]] || { cat $W/SOURCE.txt; echo "SETUP CHECK FAILED"; exit 1; }
echo "$N ok"
